# quarter = bottom-left after folding top->bottom and right->left; cuts: E near left edge (just below middle), reversed-E near bottom centre
cuts=[('E',('left','below-mid')),('R',('centre-left','bottom'))]
flip={'E':'R','R':'E'}
res=set()
for s,(x,y) in cuts:
    for mx in (False,True):
        for my in (False,True):
            xx={'left':'right','centre-left':'centre-right'}[x] if mx else x
            yy={'below-mid':'above-mid','bottom':'top'}[y] if my else y
            ss=flip[s] if mx else s   # E is symmetric top-bottom
            res.add((ss,xx,yy))
